// La lista de clientes NO vive aquí: vive en la pestaña `clientes` de la hoja maestra,
// que rellena el agente al dar de alta al cliente. Así no hay que abrir n8n nunca más.
// Columnas: cliente | ad_account_id | email | logo_url | objetivos | landing_url | activo
const m = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto',
           'septiembre','octubre','noviembre','diciembre'];
const hoy = new Date();
const fin = new Date(hoy); fin.setDate(hoy.getDate() - 1);        // hasta ayer (jueves)
const ini = new Date(fin); ini.setDate(fin.getDate() - 6);
const semana = `Semana del ${ini.getDate()} al ${fin.getDate()} de ${m[fin.getMonth()]}`;

return $input.all()
  .map(i => i.json)
  .filter(c => c.ad_account_id && c.email && String(c.activo).toLowerCase() !== 'no')
  .map(c => {
    let objetivos = {};
    try { objetivos = c.objetivos ? JSON.parse(c.objetivos) : {}; } catch (e) { objetivos = {}; }
    return { json: { ...c, objetivos, semana,
             desde: ini.toISOString().slice(0,10), hasta: fin.toISOString().slice(0,10) } };
  });

// Construye el HTML del reporte semanal (mismo diseño que el aprobado por Dirección).
const eur = x => '€' + x.toLocaleString('es-ES', {minimumFractionDigits:2, maximumFractionDigits:2});
const cli = $('Uno por uno').first().json;
const filas = $input.first().json.data || [];

const camp = filas.map(r => {
  const gasto = parseFloat(r.spend || 0);
  const acc = (r.actions || []).find(a => a.action_type === 'lead'
            || a.action_type === 'offsite_conversion.fb_pixel_lead');
  return { nombre: r.campaign_name, gasto, leads: acc ? parseInt(acc.value) : 0,
           objetivo: (cli.objetivos || {})[r.campaign_name] || '' };
});
const activas = camp.filter(c => c.gasto > 0).sort((a,b) => b.gasto - a.gasto);
const sinInv  = camp.length - activas.length;
const gasto = activas.reduce((s,c) => s + c.gasto, 0);
const leads = activas.reduce((s,c) => s + c.leads, 0);
const cpl = leads ? eur(gasto/leads) : '—';

const mini = (t,v) => `<td width="33%" valign="top" style="padding:0 4px"><table role="presentation" width="100%" style="background:#faf9fc;border-radius:6px"><tr><td style="padding:10px 12px"><div style="font-size:10px;color:#8a8a94;font-weight:700">${t}</div><div style="font-size:16px;font-weight:800;color:#0b0b0f;margin-top:3px">${v}</div></td></tr></table></td>`;
const tarjetas = activas.map(c => `<table role="presentation" width="100%" style="border:1px solid #e6e6ea;border-radius:8px;margin-top:10px"><tr><td style="padding:14px 14px 8px"><div style="font-size:14px;font-weight:800;color:#0b0b0f">${c.nombre}</div>${c.objetivo ? `<div style="font-size:12px;color:#6b6b76;margin-top:3px">Objetivo: ${c.objetivo}</div>` : ''}<table role="presentation" width="100%" style="margin-top:10px"><tr>${mini('Invertido', eur(c.gasto))}${mini('Clientes potenciales', String(c.leads))}${mini('Coste x c. potencial', c.leads ? eur(c.gasto/c.leads) : '—')}</tr></table></td></tr></table>`).join('');
const nota = sinInv ? `<div style="margin-top:10px;font-size:11px;color:#9a9aa4">+ ${sinInv} campaña${sinInv!==1?'s':''} sin inversión esta semana.</div>` : '';

const card = (t,v,d,color) => `<td width="33%" valign="top" style="padding:0 4px"><table role="presentation" width="100%" style="border:1px solid #e6e6ea;border-radius:8px"><tr><td style="padding:14px"><div style="font-size:12px;font-weight:700;color:#0b0b0f">${t}</div><div style="font-size:24px;font-weight:800;color:${color};margin:6px 0">${v}</div><div style="font-size:11px;color:#8a8a94">${d}</div></td></tr></table></td>`;
const tot = (t,v) => `<td style="padding:16px 18px"><div style="color:#c9c9d1;font-size:11px;font-weight:700">${t}</div><div style="color:#fff;font-size:20px;font-weight:800;margin-top:4px">${v}</div></td>`;

const html = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5;padding:24px 0;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:600px;max-width:100%;background:#fff;border-radius:10px;overflow:hidden">
<tr><td style="background:#0b0b0f;padding:18px 24px"><table role="presentation" width="100%"><tr><td style="color:#fff;font-size:20px;font-weight:800;letter-spacing:-.5px"><img src="https://<tu-subdominio>/brand/flowboost-black.png" alt="Flowboost" width="150" height="33" style="width:150px;height:33px;display:block;border:0"></td><td align="right" style="color:#c9c9d1;font-size:12px">Meta Ads</td></tr></table></td></tr>
<tr><td style="height:4px;background:#7c5cff;font-size:0;line-height:0">&nbsp;</td></tr>
<tr><td style="padding:26px 24px 8px">
${cli.logo_url ? `<table role="presentation" style="border:1px solid #e6e6ea;border-radius:8px"><tr><td style="padding:12px 16px"><img src="${cli.logo_url}" alt="${cli.cliente}" height="28" style="height:28px;display:block"></td></tr></table>` : ''}
<div style="margin-top:18px;color:#7c5cff;font-size:12px;font-weight:700;letter-spacing:.6px">REPORTE SEMANAL DE RESULTADOS</div>
<div style="margin-top:6px;font-size:26px;font-weight:800;color:#0b0b0f">${cli.cliente}</div>
<div style="margin-top:4px;color:#6b6b76;font-size:14px">${cli.semana}</div>
<div style="margin-top:22px;color:#8a8a94;font-size:11px;font-weight:700;letter-spacing:.8px">RESUMEN</div>
<table role="presentation" width="100%" style="margin-top:10px"><tr>${card('Invertido', eur(gasto), 'Gasto en anuncios.', '#0b0b0f')}${card('Clientes potenciales', String(leads), 'Personas que dejaron sus datos.', '#7c5cff')}${card('Coste por cliente potencial', cpl, 'Lo que costó cada uno.', '#0b0b0f')}</tr></table>
<div style="margin-top:24px;color:#8a8a94;font-size:11px;font-weight:700;letter-spacing:.8px">CAMPAÑAS</div>${tarjetas}${nota}
</td></tr>
<tr><td style="padding:0 24px 22px"><table role="presentation" width="100%" style="background:#0b0b0f;border-radius:8px"><tr>${tot('Invertido', eur(gasto))}${tot('Clientes potenciales', String(leads))}${tot('Coste x c. potencial', cpl)}</tr></table></td></tr>
<tr><td style="border-top:1px solid #eee;padding:14px 24px;text-align:center;color:#9a9aa4;font-size:11px">Flowboost Marketing · Reporte automático semanal · datos de Meta Ads</td></tr>
</table></td></tr></table>`;

// `publicado` es el interruptor automático: sin gasto en la semana, las campañas todavía
// no están en el aire (o están pausadas) y NO se manda nada. Nadie tiene que avisar de nada.
return [{ json: { html, cliente: cli.cliente, email: cli.email, semana: cli.semana,
                  gasto: +gasto.toFixed(2), leads, cpl: leads ? +(gasto/leads).toFixed(2) : null,
                  publicado: gasto > 0 } }];
